from typing import List, Optional
from pydantic import BaseModel, Field

class Citation(BaseModel):
    """Represents a specific, auditable source citation from a corporate filing."""
    document: str = Field(description="The source file name, e.g., 'nubank-3q25.pdf'")
    page: int = Field(description="The exact 1-indexed page number in the filing")
    quote: str = Field(description="The exact snippet or metric quoted from the text")

class OperationalInsight(BaseModel):
    """The structured output generated by the financial/operational synthesis engine."""
    answer: str = Field(description="A clear, professional executive summary answering the user query.")
    citations: List[Citation] = Field(default_factory=list, description="List of source citations backing the answer.")
    is_grounded: bool = Field(default=True, description="Whether the answer is strictly backed by the provided documents.")